contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint amount, uint waitTime) public {
        require(amount <= type(uint112).max);

        c.newGrantProposal(address(this), amount);

        uint pid = c.proposalCount();
        require(pid > 0);

        bool reverted;
        if (waitTime > 0) {
            uint start = block.timestamp;
            while (block.timestamp < start + waitTime) {
                // burn time until at least waitTime seconds have passed
            }
        }

        uint beforeFinalised = c.mapPID_finalised(pid) ? 1 : 0;
        uint beforeFinalising = c.mapPID_finalising(pid) ? 1 : 0;
        uint beforeVotes = c.mapPID_votes(pid);

        try c.finaliseProposal(pid) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint afterFinalised = c.mapPID_finalised(pid) ? 1 : 0;
        uint afterFinalising = c.mapPID_finalising(pid) ? 1 : 0;
        uint afterVotes = c.mapPID_votes(pid);

        assert(
            !reverted ||
            (afterFinalised == beforeFinalised &&
             afterFinalising == beforeFinalising &&
             afterVotes == beforeVotes)
        );
    }

    receive() external payable {}
}
